import{_ as t,o as a,c as n,a2 as l}from"./chunks/framework.C-si7TFR.js";const u=JSON.parse('{"title":"组合子 Agent","description":"","frontmatter":{"title":"组合子 Agent"},"headers":[],"relativePath":"zh/guide/sub-agents.md","filePath":"zh/guide/sub-agents.md"}'),i={name:"zh/guide/sub-agents.md"};function g(r,e,o,s,A,h){return a(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="组合子-agent" tabindex="-1">组合子 Agent <a class="header-anchor" href="#组合子-agent" aria-label="Permalink to &quot;组合子 Agent&quot;">​</a></h1><p>子 Agent 用于把相对独立的任务交给另一个 Agent 配置处理。它不是无限层级编排，也不等于子流程。</p><h2 id="创建一个内置-agent" tabindex="-1">创建一个内置 Agent <a class="header-anchor" href="#创建一个内置-agent" aria-label="Permalink to &quot;创建一个内置 Agent&quot;">​</a></h2><ol><li>打开主 Agent 卡片的操作菜单，选择添加内置 Agent。</li><li>在主卡的内置 Agent 区域打开其配置。</li><li>写清该 Agent 负责的任务边界，只选择它需要的工具。</li><li>回到主 Agent 配置，在子 Agent 区域选择这个内置 Agent。</li><li>保存后从主 Agent 发起一个可验证的小任务，并在链路中检查子 Agent 调用。</li></ol><p>当前入口只显示主 Agent 配置的直接子 Agent 选择，不承诺任意层级或递归调用。需要严格确定的步骤、顺序和失败分支时，优先使用<a href="./workflows.html">工作流</a>或<a href="./../sub_workflow.html">子流程节点</a>。</p><h2 id="配置边界" tabindex="-1">配置边界 <a class="header-anchor" href="#配置边界" aria-label="Permalink to &quot;配置边界&quot;">​</a></h2><ul><li>内置 Agent 随主卡组织，不要把它当作独立 Agent 重复创建。</li><li>主 Agent 的任务分配、子 Agent 的指令和工具权限共同影响结果。</li><li>一个 Agent 被其他 Agent 引用时，先检查引用关系再删除或修改。</li><li>使用升级操作将内置 Agent 改为独立 Agent 前，确认后续归属和迁移范围符合预期。</li></ul><h2 id="排查" tabindex="-1">排查 <a class="header-anchor" href="#排查" aria-label="Permalink to &quot;排查&quot;">​</a></h2><p>没有调用子 Agent 时，检查主 Agent 的子 Agent 选择、模型行为和任务描述；调用失败时检查子 Agent 的工具、模型和权限，不要仅靠增加循环或重试解决。</p>',9)])])}const _=t(i,[["render",g]]);export{u as __pageData,_ as default};
